-- Local test only. Stop MainServer normally and verify redo.* are empty before running.
-- Restores only the captured two test characters and the single recorded test trade.
START TRANSACTION;
SET @restore_ok = (SELECT COUNT(*)=2 FROM game.characters c JOIN login.users u ON u.user_id=c.user_id WHERE (c.char_id=5011 AND u.login_id='unity_ai_01') OR (c.char_id=5012 AND u.login_id='unity_ai_02'));
SET @restore_ok = @restore_ok AND (SELECT COUNT(*)=1 AND COALESCE(SUM(listing_id IN ('180')),0)=1 FROM bazaar.bazaar WHERE seller_id IN (5011,5012) OR buyer_id IN (5011,5012));
SET @restore_ok = @restore_ok AND (SELECT COUNT(*)=1 FROM bazaar.bazaar WHERE listing_id='180' AND seller_id=5011 AND buyer_id <=> '5012' AND item_id=1 AND quantity=1 AND price=10);
DELETE FROM bazaar.bazaar_log WHERE @restore_ok=1 AND listing_id='180';
DELETE FROM bazaar.bazaar_claim WHERE @restore_ok=1 AND listing_id='180';
DELETE FROM bazaar.buyer_outbox WHERE @restore_ok=1 AND listing_id='180';
DELETE FROM bazaar.bazaar WHERE @restore_ok=1 AND listing_id='180';
UPDATE game.characters SET `level`=1,`exp`='10',`hp`=9850,`mp`=9919,`max_hp`=10000,`max_mp`=10000,`attack`=10,`dir`=2,`zone_id`=1,`last_pos_x`=10.3088,`last_pos_y`=10.8893,`deleted_at`=NULL WHERE @restore_ok=1 AND char_id='5011' AND user_id='6981';
UPDATE game.characters SET `level`=1,`exp`='30',`hp`=7575,`mp`=9777,`max_hp`=10000,`max_mp`=10000,`attack`=10,`dir`=1,`zone_id`=2,`last_pos_x`=283.343,`last_pos_y`=10.9752,`deleted_at`=NULL WHERE @restore_ok=1 AND char_id='5012' AND user_id='6982';
INSERT INTO game.characters_inventory (`char_id`,`inventory`) SELECT '5011',UNHEX('') WHERE @restore_ok=1 ON DUPLICATE KEY UPDATE `inventory`=VALUES(`inventory`);
INSERT INTO game.characters_inventory (`char_id`,`inventory`) SELECT '5012',UNHEX('') WHERE @restore_ok=1 ON DUPLICATE KEY UPDATE `inventory`=VALUES(`inventory`);
DELETE FROM game.characters_currency WHERE @restore_ok=1 AND char_id=5011;
DELETE FROM game.characters_currency WHERE @restore_ok=1 AND char_id=5012;
DELETE FROM bazaar.characters_diamond WHERE @restore_ok=1 AND char_id=5011;
DELETE FROM bazaar.characters_diamond WHERE @restore_ok=1 AND char_id=5012;
SELECT @restore_ok AS identity_guard, 1 AS test_trades_to_restore;
COMMIT;
